BEGIN
    IF (OLD.order_number != NEW.order_number 
        OR OLD.account_number != NEW.account_number 
        OR OLD.mobile_number != NEW.mobile_number) THEN

        -- Set these columns to NULL if any of the conditions are true
        SET NEW.mo_reconciliation_ref_id = NULL;
        SET NEW.mo_reconciliation_ref_id_2 = NULL;
        SET NEW.mo_reconciliation_ref_id_3 = NULL;
        SET NEW.mo_reconciliation_ref_id_4 = NULL;
        SET NEW.mo_general_ref_id = NULL;
    END IF;
END

BEGIN
    -- SECOND BLOCK
    -- Additional nulling if product class or package changes
    IF OLD.package_name != NEW.package_name THEN
        SET NEW.mo_reconciliation_ref_id = NULL;
    END IF;

    -- FOURTH BLOCK
    IF
        OLD.order_number != NEW.order_number OR
        OLD.account_number != NEW.account_number OR
        OLD.customer_name != NEW.customer_name OR
        OLD.mobile_number != NEW.mobile_number OR
        OLD.carrier_system != NEW.carrier_system OR
        OLD.ref_login_username_id != NEW.ref_login_username_id
    THEN
        SET NEW.mo_reconciliation_ref_id = NULL;
        SET NEW.mo_reconciliation_ref_id_2 = NULL;
        SET NEW.mo_reconciliation_ref_id_3 = NULL;
        SET NEW.mo_reconciliation_ref_id_4 = NULL;
        SET NEW.mo_general_ref_id = NULL;
    END IF;

    IF NOT (OLD.employee_id <=> NEW.employee_id)
       OR NOT (OLD.ref_login_username_id <=> NEW.ref_login_username_id)
       OR NOT (OLD.order_date <=> NEW.order_date)
       OR (NEW.seller_ref_id IS NULL AND OLD.seller_ref_id IS NOT NULL)
       OR (NEW.upline_ref_id IS NULL AND OLD.upline_ref_id IS NOT NULL)
       OR (NEW.seller_ref_id_level_1 IS NULL AND OLD.seller_ref_id_level_1 IS NOT NULL)
       OR (NEW.upline_ref_id_level_1 IS NULL AND OLD.upline_ref_id_level_1 IS NOT NULL)
       OR (NEW.seller_ref_id_level_2 IS NULL AND OLD.seller_ref_id_level_2 IS NOT NULL)
       OR (NEW.upline_ref_id_level_2 IS NULL AND OLD.upline_ref_id_level_2 IS NOT NULL)
       OR (NEW.seller_ref_id_level_3 IS NULL AND OLD.seller_ref_id_level_3 IS NOT NULL)
       OR (NEW.upline_ref_id_level_3 IS NULL AND OLD.upline_ref_id_level_3 IS NOT NULL) 
    THEN
        -- Clear all alignment fields
        SET NEW.seller_ref_id = NULL;
        SET NEW.upline_ref_id = NULL;
        SET NEW.seller_ref_id_level_1 = NULL;
        SET NEW.upline_ref_id_level_1 = NULL;
        SET NEW.seller_ref_id_level_2 = NULL;
        SET NEW.upline_ref_id_level_2 = NULL;
        SET NEW.seller_ref_id_level_3 = NULL;
        SET NEW.upline_ref_id_level_3 = NULL;
    END IF;
END

procedures.contentString:
BEGIN
    -- Declare variables
    DECLARE v_db_id VARCHAR(50);
    DECLARE v_prodclass VARCHAR(50);
    DECLARE v_empalign VARCHAR(50);
    DECLARE v_markalign VARCHAR(50);
    DECLARE v_regalign VARCHAR(50);
    DECLARE v_divalign VARCHAR(50);
    DECLARE v_employee_id VARCHAR(50);
    DECLARE v_username VARCHAR(50);
    DECLARE v_order_date DATETIME(6);
    DECLARE v_package_name VARCHAR(250);
    DECLARE v_purchase_type VARCHAR(50);
    DECLARE v_carrier_system VARCHAR(50);
    DECLARE v_primary_carrier VARCHAR(50);
    DECLARE v_channel VARCHAR(50);
    DECLARE done INT DEFAULT 0;
    DECLARE v_not_found INT DEFAULT 0;

    -- Declare cursor to fetch needed records
    DECLARE cur CURSOR FOR
        SELECT db_id, prodclass_ref_id, empalign_ref_id, markalign_ref_id,
               regalign_ref_id, divalign_ref_id, order_date, employee_id,
               package_name, purchase_type, carrier_system, ref_login_username_id
        FROM master_raw_orders
        WHERE prodclass_ref_id IS NULL
           OR empalign_ref_id IS NULL
           OR markalign_ref_id IS NULL
           OR regalign_ref_id IS NULL
           OR divalign_ref_id IS NULL
           OR employee_id IS NULL;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    -- Open cursor
    OPEN cur;

    read_loop: LOOP
        -- Fetch next row
        FETCH cur INTO v_db_id, v_prodclass, v_empalign, v_markalign,
                      v_regalign, v_divalign, v_order_date, v_employee_id,
                      v_package_name, v_purchase_type, v_carrier_system, v_username;

        IF done THEN
            LEAVE read_loop;
        END IF;

        -- If employee_id is null, try to fetch it using username
        IF v_employee_id IS NULL AND v_username IS NOT NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT l.employee_id INTO v_employee_id
                FROM airtable.align_logins l
                WHERE l.username = v_username
                LIMIT 1;
            END;
        END IF;

        -- EMPLOYEE ALIGNMENT
        IF v_empalign IS NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT e.db_id INTO v_empalign
                FROM airtable.align_employee_alignment e
                WHERE e.employee_id = v_employee_id
                  AND v_order_date BETWEEN e.start_date AND DATE_ADD(e.check_date, INTERVAL 1 DAY)
                LIMIT 1;
            END;
            IF v_not_found = 1 THEN
                SET v_empalign = NULL;
            END IF;
        END IF;

        -- MARKET ALIGNMENT
        IF v_markalign IS NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT m.db_id, m.primary_carrier, m.channel
                INTO v_markalign, v_primary_carrier, v_channel
                FROM airtable.align_market_alignment m
                LEFT JOIN airtable.align_employee_alignment e ON e.db_id = v_empalign
                WHERE m.dept_code = e.dept_code
                  AND v_order_date BETWEEN m.start_date AND DATE_ADD(m.check_date, INTERVAL 1 DAY)
                LIMIT 1;
            END;
            IF v_not_found = 1 THEN
                SET v_markalign = NULL;
                SET v_primary_carrier = NULL;
                SET v_channel = NULL;
            END IF;
        ELSE
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT db_id, primary_carrier, channel
                INTO v_markalign, v_primary_carrier, v_channel
                FROM airtable.align_market_alignment
                WHERE db_id = v_markalign;
            END;
            IF v_not_found = 1 THEN
                SET v_markalign = NULL;
                SET v_primary_carrier = NULL;
                SET v_channel = NULL;
            END IF;
        END IF;

        -- REGION ALIGNMENT
        IF v_regalign IS NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT r.db_id INTO v_regalign
                FROM airtable.align_region_alignment r
                LEFT JOIN airtable.align_market_alignment m ON m.db_id = v_markalign
                WHERE r.region_code = m.assigned_to_region_code
                  AND v_order_date BETWEEN r.start_date AND DATE_ADD(r.check_date, INTERVAL 1 DAY)
                LIMIT 1;
            END;
            IF v_not_found = 1 THEN
                SET v_regalign = NULL;
            END IF;
        END IF;

        -- DIVISION ALIGNMENT
        IF v_divalign IS NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT d.db_id INTO v_divalign
                FROM airtable.align_division_alignment d
                JOIN airtable.align_region_alignment r ON r.assigned_to_division_code = d.division_code
                WHERE r.db_id = v_regalign
                  AND v_order_date BETWEEN d.start_date AND DATE_ADD(d.check_date, INTERVAL 1 DAY)
                LIMIT 1;
            END;
            IF v_not_found = 1 THEN
                SET v_divalign = NULL;
            END IF;
        END IF;

        -- PRODUCT CLASSIFICATION
        IF v_prodclass IS NULL THEN
            SET v_not_found = 0;
            BEGIN
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_not_found = 1;
                SELECT pc.db_id INTO v_prodclass
                FROM airtable.align_product_classification_current pc
                LEFT JOIN airtable.align_unit_weights uw
                    ON uw.carrier = v_primary_carrier AND uw.channel = v_channel
                WHERE coalesce(uw.program_id,'1') = pc.program_id
                  AND pc.package_name = v_package_name
                  AND pc.purchase_type = v_purchase_type
                  AND (
                      CASE 
                          WHEN v_carrier_system IN ('dsi','sp video','dtv','sp internet','sp mobility') THEN 'saraplus' 
                          WHEN v_carrier_system LIKE 'lumos%' THEN 'pops' 
                          ELSE v_carrier_system
                      END
                  ) = pc.system_type
                LIMIT 1;
            END;
            IF v_not_found = 1 THEN
                SET v_prodclass = NULL;
            END IF;
        END IF;

        -- FINAL UPDATE
        UPDATE master_raw_orders mro
        SET
            prodclass_ref_id = v_prodclass,
            empalign_ref_id = v_empalign,
            markalign_ref_id = v_markalign,
            regalign_ref_id = v_regalign,
            divalign_ref_id = v_divalign,
            employee_id = v_employee_id
        WHERE mro.db_id = v_db_id;

    END LOOP;

    CLOSE cur;
END

